import {
  ArrowDownRightIcon,
  ArrowUpRightIcon,
  CircleDollarSignIcon,
  MousePointerClickIcon,
  UserRoundCheckIcon,
  UsersIcon,
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { IconTile } from "@/components/ui/icon-tile";

const metrics = [
  {
    change: "+12.5%",
    icon: UsersIcon,
    label: "Total visitors",
    positive: true,
    value: "42,890",
  },
  {
    change: "+8.2%",
    icon: UserRoundCheckIcon,
    label: "New customers",
    positive: true,
    value: "3,284",
  },
  {
    change: "-1.4%",
    icon: MousePointerClickIcon,
    label: "Conversion rate",
    positive: false,
    value: "4.21%",
  },
  {
    change: "+16.8%",
    icon: CircleDollarSignIcon,
    label: "Net revenue",
    positive: true,
    value: "$128.4k",
  },
];

export const OverviewCards = () => (
  <section
    aria-label="Performance overview"
    className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"
  >
    {metrics.map((metric) => (
      <Card key={metric.label}>
        <CardHeader className="flex-row items-start justify-between gap-3">
          <div>
            <CardDescription>{metric.label}</CardDescription>
            <CardTitle className="mt-2 font-semibold text-2xl tabular-nums tracking-[-0.02em]">
              {metric.value}
            </CardTitle>
          </div>
          <IconTile
            aria-hidden="true"
            className="size-9 border-transparent bg-muted shadow-none"
            size="sm"
          >
            <metric.icon aria-hidden="true" className="size-4" />
          </IconTile>
        </CardHeader>
        <CardContent>
          <Badge variant={metric.positive ? "secondary" : "outline"}>
            {metric.positive ? (
              <ArrowUpRightIcon aria-hidden="true" className="size-3" />
            ) : (
              <ArrowDownRightIcon aria-hidden="true" className="size-3" />
            )}
            {metric.change}
          </Badge>
          <span className="ms-2 text-muted-foreground text-xs">
            vs. last month
          </span>
        </CardContent>
      </Card>
    ))}
  </section>
);

"use client";

import { Area, AreaChart, CartesianGrid, XAxis, YAxis } from "recharts";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  type ChartConfig,
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
} from "@/components/ui/chart";

export const VisitorsChart = () => (
  <Card>
    <CardHeader>
      <CardTitle>Visitors</CardTitle>
      <CardDescription>Unique visitors over the last 30 days</CardDescription>
    </CardHeader>
    <CardContent>
      <ChartContainer className="h-[300px] w-full" config={chartConfig}>
        <AreaChart
          accessibilityLayer
          data={chartData}
          margin={{ left: -16, right: 8 }}
        >
          <defs>
            <linearGradient id="visitors-fill" x1="0" x2="0" y1="0" y2="1">
              <stop
                offset="5%"
                stopColor="var(--color-visitors)"
                stopOpacity={0.28}
              />
              <stop
                offset="95%"
                stopColor="var(--color-visitors)"
                stopOpacity={0.02}
              />
            </linearGradient>
          </defs>
          <CartesianGrid vertical={false} />
          <XAxis
            axisLine={false}
            dataKey="date"
            tickLine={false}
            tickMargin={12}
          />
          <YAxis axisLine={false} tickLine={false} tickMargin={8} width={48} />
          <ChartTooltip content={ChartTooltipContent} />
          <Area
            dataKey="visitors"
            fill="url(#visitors-fill)"
            stroke="var(--color-visitors)"
            strokeWidth={2}
            type="monotone"
          />
        </AreaChart>
      </ChartContainer>
    </CardContent>
  </Card>
);

const chartData = [
  { date: "May 26", visitors: 1860 },
  { date: "May 31", visitors: 2240 },
  { date: "Jun 05", visitors: 2180 },
  { date: "Jun 10", visitors: 2910 },
  { date: "Jun 15", visitors: 2680 },
  { date: "Jun 20", visitors: 3420 },
  { date: "Jun 24", visitors: 3890 },
];

const chartConfig = {
  visitors: {
    color: "var(--primary)",
    label: "Visitors",
  },
} satisfies ChartConfig;

import { Badge } from "@/components/ui/badge";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

interface Channel {
  channel: string;
  conversion: string;
  trend: string;
  visitors: number;
}

interface ChannelsTableProps {
  data: Channel[];
}

export const ChannelsTable = ({ data }: ChannelsTableProps) => (
  <Card>
    <CardHeader>
      <CardTitle>Top channels</CardTitle>
      <CardDescription>Acquisition performance by source</CardDescription>
    </CardHeader>
    <CardContent className="px-0">
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead className="ps-6">Channel</TableHead>
            <TableHead>Visitors</TableHead>
            <TableHead className="pe-6 text-end">Trend</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {data.map((channel) => (
            <TableRow key={channel.channel}>
              <TableCell className="ps-6">
                <span className="block font-medium">{channel.channel}</span>
                <span className="text-muted-foreground text-xs">
                  {channel.conversion} conversion
                </span>
              </TableCell>
              <TableCell className="tabular-nums">
                {channel.visitors.toLocaleString("en-US")}
              </TableCell>
              <TableCell className="pe-6 text-end">
                <Badge
                  variant={
                    channel.trend.startsWith("+") ? "secondary" : "outline"
                  }
                >
                  {channel.trend}
                </Badge>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </CardContent>
  </Card>
);
